export class LagrangeClient {
  public readonly transport: AshTransport;
  public readonly planet: PlanetClient;
  public readonly port: PortClient;
  public readonly berth: BerthClient;
  public readonly berthReservation: BerthReservationClient;
  public readonly shippingLine: ShippingLineClient;
  public readonly crewMember: CrewMemberClient;
  public readonly transponder: TransponderClient;
  public readonly ship: ShipClient;
  public readonly contract: ContractClient;
  public readonly container: ContainerClient;
  public readonly voyage: VoyageClient;
  public readonly stowage: StowageClient;
  public readonly telemetryPing: TelemetryPingClient;
  public readonly opsEvent: OpsEventClient;
  public readonly world: WorldDomainClient;
  public readonly fleet: FleetDomainClient;
  public readonly cargo: CargoDomainClient;
  public readonly telemetry: TelemetryDomainClient;

  constructor(config: AshClientConfig) {
    this.transport = new AshTransport(config);
    this.planet = new PlanetClient(this.transport);
    this.port = new PortClient(this.transport);
    this.berth = new BerthClient(this.transport);
    this.berthReservation = new BerthReservationClient(this.transport);
    this.shippingLine = new ShippingLineClient(this.transport);
    this.crewMember = new CrewMemberClient(this.transport);
    this.transponder = new TransponderClient(this.transport);
    this.ship = new ShipClient(this.transport);
    this.contract = new ContractClient(this.transport);
    this.container = new ContainerClient(this.transport);
    this.voyage = new VoyageClient(this.transport);
    this.stowage = new StowageClient(this.transport);
    this.telemetryPing = new TelemetryPingClient(this.transport);
    this.opsEvent = new OpsEventClient(this.transport);
    this.world = new WorldDomainClient(this.transport);
    this.fleet = new FleetDomainClient(this.transport);
    this.cargo = new CargoDomainClient(this.transport);
    this.telemetry = new TelemetryDomainClient(this.transport);
  }
}

export function createLagrangeClient(config: AshClientConfig): LagrangeClient {
  return new LagrangeClient(config);
}

